//! Inline SVG icons and identicons, so the pages need no icon font, image
//! files or JavaScript (the CSP allows none of them). Everything returned here
//! is generated by us from fixed data or a hash, never from user input, which
//! is why the templates may print it unescaped.

use std::fmt::Write;

use sha2::{Digest, Sha256};

const ATTRS: &str = r#"class="icon" viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true""#;

