/// `<svg>` for `name`, or an empty string for an unknown name.
pub fn icon(name: &str) -> String {
    shapes(name).map_or_else(String::new, |inner| format!("<svg {ATTRS}>{inner}</svg>"))
}

/// A 5x5, left-right symmetric pattern and colour taken from a hash of `seed`:
/// the same seed always looks the same, different seeds look different.
pub fn identicon(seed: &str) -> String {
    let hash = Sha256::digest(seed.as_bytes());
    let hue = u32::from(hash[0]) * 360 / 256;

    let mut cells = String::new();
    for row in 0..5usize {
        for col in 0..3usize {
            let bit = row * 3 + col;
            if hash[1 + bit / 8] >> (bit % 8) & 1 == 1 {
                let _ = write!(cells, r#"<rect x="{col}" y="{row}" width="1" height="1"/>"#);
                if col < 2 {
                    let _ = write!(
                        cells,
                        r#"<rect x="{}" y="{row}" width="1" height="1"/>"#,
                        4 - col
                    );
                }
            }
        }
    }
    format!(
        r#"<svg class="identicon" viewBox="0 0 5 5" width="20" height="20" aria-hidden="true"><rect width="5" height="5" fill="hsl({hue},30%,92%)"/><g fill="hsl({hue},55%,42%)">{cells}</g></svg>"#
    )
}

#[cfg(test)]
mod tests {
    use std::collections::BTreeSet;

    use super::*;

    const TEMPLATES: &[&str] = &[
        include_str!("../../templates/layout.html"),
        include_str!("../../templates/index.html"),
        include_str!("../../templates/dashboard.html"),
        include_str!("../../templates/details.html"),
        include_str!("../../templates/share.html"),
        include_str!("../../templates/stats.html"),
        include_str!("../../templates/analysis.html"),
    ];

    /// Every `icon("name")` the templates and the error page ask for.
    fn used_icons() -> BTreeSet<String> {
        let mut names: BTreeSet<String> = ["alert-triangle", "lock", "search", "activity"]
            .map(String::from)
            .into();
        for template in TEMPLATES {
            for part in template.split("icon(\"").skip(1) {
                if let Some((name, _)) = part.split_once('"') {
                    names.insert(name.to_string());
                }
            }
        }
        names
    }

    #[test]
    fn every_icon_the_pages_use_exists_and_is_well_formed() {
        let names = used_icons();
        assert!(names.len() > 15, "{names:?}");
        for name in names {
            let svg = icon(&name);
            assert!(
                svg.starts_with("<svg class=\"icon\"") && svg.ends_with("</svg>"),
                "{name}: {svg}"
            );
            assert_eq!(svg.matches('<').count(), svg.matches('>').count(), "{name}");
            assert!(
                !svg.contains("style="),
                "{name}: inline styles are blocked by the CSP"
            );
        }
    }

    #[test]
    fn unknown_icons_are_empty_not_an_injection_point() {
        for name in ["", "nope", "x\"><script>alert(1)</script>", "../etc"] {
            assert_eq!(icon(name), "", "{name:?}");
        }
    }

    fn cells(svg: &str) -> BTreeSet<(u8, u8)> {
        svg.split("<rect x=\"")
            .skip(1) // the text before the first cell (the background has no x)
            .map(|r| {
                let (x, rest) = r.split_once("\" y=\"").unwrap();
                let (y, _) = rest.split_once('"').unwrap();
                (x.parse().unwrap(), y.parse().unwrap())
            })
            .collect()
    }

    #[test]
    fn identicons_are_stable_symmetric_and_vary() {
        let a = identicon("./srcds +map de_dust2");
        assert_eq!(a, identicon("./srcds +map de_dust2"));
        assert!(a.starts_with("<svg class=\"identicon\"") && a.ends_with("</svg>"));
        assert!(
            !a.contains("srcds"),
            "the seed itself must not leak into the markup"
        );

        for seed in ["a", "b", "c", "server one", "server two"] {
            let cells = cells(&identicon(seed));
            assert!(cells.iter().all(|&(x, y)| x < 5 && y < 5));
            for &(x, y) in &cells {
                assert!(
                    cells.contains(&(4 - x, y)),
                    "{seed}: ({x},{y}) has no mirror image"
                );
            }
        }
        let distinct: BTreeSet<String> =
            (0..40).map(|i| identicon(&format!("server {i}"))).collect();
        assert!(distinct.len() > 35, "{}", distinct.len());
    }
}
